from pyspark.sql import functions as F
from pyspark.sql.types import StructType

cols = []
for field in sensor_readings.schema.fields:
    if isinstance(field.dataType, StructType):
        for inner in field.dataType.fields:
            cols.append(F.col(field.name + "." + inner.name).alias(field.name + "_" + inner.name))
    else:
        cols.append(F.col(field.name))

flat = sensor_readings.select(cols)
print(flat.columns)
flat.select("reading_id", "payload_temperature_c", "payload_tags", "firmware_version").show(3, truncate=False)
